// 4. Destructuring and spread, the way props and state updates use them
const user = { name: "Asha", age: 14, city: "Pune" };
const { name, ...rest } = user;
console.log(name, rest);

const older = { ...user, age: user.age + 1 };
console.log(user.age, older.age);

// 1. Mutating state keeps the same reference, so React sees "no change"
const todos = ["read", "code"];
const sameList = todos;
sameList.push("sleep");
console.log("mutated, same object?", Object.is(todos, sameList));

const newList = [...todos, "eat"];
console.log("copied, same object?", Object.is(todos, newList));
console.log(newList);

// 3. map returns a new array, filter keeps what passes
const students = [
  { id: 1, name: "Asha", score: 82 },
  { id: 2, name: "Ben", score: 47 },
  { id: 3, name: "Chen", score: 91 },
];
const passed = students.filter(s => s.score >= 50);
const rows = passed.map(s => `<li key=${s.id}>${s.name}: ${s.score}</li>`);
console.log(rows);
console.log("original untouched:", students.length);

// 2. && returns the left side when it is falsy
const count = 0;
console.log(count && "You have messages");
console.log(count > 0 && "You have messages");
console.log(3 && "You have messages");

// 5. Each "render" creates a handler that remembers that render's value
let count = 0;
function render() {
  const countThisRender = count;
  return function handleClick() {
    console.log("this handler sees", countThisRender);
  };
}
const firstHandler = render();
count = 5;
const secondHandler = render();
firstHandler();
secondHandler();

// 6. async/await: the order things actually happen
function fakeFetch(data, ms) {
  return new Promise(resolve => setTimeout(() => resolve(data), ms));
}
async function loadProfile() {
  console.log("1. request sent");
  const profile = await fakeFetch({ name: "Asha" }, 100);
  console.log("3. data arrived:", profile.name);
}
loadProfile();
console.log("2. page keeps rendering meanwhile");
